```java
import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import java.util.List;

public class LocatorPractice {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();

        try {
            // Open Google
            driver.get("https://www.google.com");
            System.out.println("Opened Google.com");
            System.out.println("Page title: " + driver.getTitle());
            System.out.println("-".repeat(50));

            // Method 1: Locate search box by NAME
            System.out.println("\n1. Locating search box by NAME:");
            WebElement searchBox1 = driver.findElement(By.name("q"));
            System.out.println("   Found using By.name('q'): " + (searchBox1 != null));
            System.out.println("   Tag: " + searchBox1.getTagName());

            // Method 2: Locate search box by CSS SELECTOR
            System.out.println("\n2. Locating search box by CSS SELECTOR:");
            WebElement searchBox2 = driver.findElement(By.cssSelector("textarea[name='q']"));
            System.out.println("   Found using By.cssSelector: " + (searchBox2 != null));
            System.out.println("   Title attribute: " + searchBox2.getAttribute("title"));

            // Method 3: Locate search box by XPATH
            System.out.println("\n3. Locating search box by XPATH:");
            WebElement searchBox3 = driver.findElement(By.xpath("//textarea[@name='q']"));
            System.out.println("   Found using By.xpath: " + (searchBox3 != null));
            System.out.println("   Max length: " + searchBox3.getAttribute("maxlength"));

            // Verify all three locators found the same element
            System.out.println("\n4. Verifying all locators found same element:");
            boolean sameElement = searchBox1.equals(searchBox2) && searchBox2.equals(searchBox3);
            System.out.println("   All three locators found the same element: " + sameElement);

            System.out.println("\n" + "-".repeat(50));

            // Find and count all links
            System.out.println("\n5. Finding all links on the page:");
            List<WebElement> allLinks = driver.findElements(By.tagName("a"));
            System.out.println("   Total links found: " + allLinks.size());

            // Count links with text vs without text
            int linksWithText = 0;
            int linksWithoutText = 0;

            System.out.println("\n   First 10 links with text:");
            int count = 0;
            for (WebElement link : allLinks) {
                String linkText = link.getText();
                if (linkText != null && !linkText.trim().isEmpty()) {
                    linksWithText++;
                    if (count < 10) {
                        System.out.println("   - " + linkText);
                        count++;
                    }
                } else {
                    linksWithoutText++;
                }
            }

            System.out.println("\n6. Link Statistics:");
            System.out.println("   Links with text: " + linksWithText);
            System.out.println("   Links without text: " + linksWithoutText);
            System.out.println("   Total links: " + allLinks.size());

            // Bonus: Find links with href
            System.out.println("\n7. Analyzing link attributes:");
            int validHrefCount = 0;
            for (WebElement link : allLinks) {
                String href = link.getAttribute("href");
                if (href != null && !href.isEmpty()) {
                    validHrefCount++;
                }
            }
            System.out.println("   Links with valid href: " + validHrefCount);

            // Demonstrate usage of the search box
            System.out.println("\n8. Testing search box interaction:");
            searchBox1.clear();
            searchBox1.sendKeys("Selenium WebDriver");
            System.out.println("   Entered text: Selenium WebDriver");
            System.out.println("   Current value: " + searchBox1.getAttribute("value"));

            System.out.println("\n" + "=".repeat(50));
            System.out.println("Test completed successfully!");

        } catch (Exception e) {
            System.err.println("Error occurred: " + e.getMessage());
            e.printStackTrace();
        } finally {
            // Close browser
            driver.quit();
            System.out.println("Browser closed.");
        }
    }
}
